"use client"

// Bollard UI — print-guard · MIT licence · https://bollard-ui.vercel.app/components/print-guard

import * as React from "react"
import { ChevronsDownUp, Link2Off, Moon, Printer, Scissors, Table, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { A4_CONTENT_WIDTH, applyPrintFixes, printFixCss, scanForPrint, type PrintIssue, type PrintIssueKind } from "./print-scan"

export * from "./print-scan"

const button =
  "inline-flex h-9 shrink-0 items-center justify-center gap-1.5 rounded-md px-4 text-sm font-medium whitespace-nowrap outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50"
const small = "inline-flex h-8 shrink-0 items-center justify-center gap-1.5 rounded-md px-3 text-sm font-medium whitespace-nowrap outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50"
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 text-xs font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

const icons: Record<PrintIssueKind, typeof Moon> = { dark: Moon, collapsed: ChevronsDownUp, wide: Table, clipped: Scissors, links: Link2Off }

const plural = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`

/** English wording for each issue: what goes wrong on paper, and what the fix does. */
export function describePrintIssue({ kind, count, cut = 0 }: PrintIssue) {
  return {
    dark: { problem: `${plural(count, "dark section", "dark sections")}: light text may print faint or invisible`, fix: "Print that text in black" },
    collapsed: { problem: `${plural(count, "collapsed section won't", "collapsed sections won't")} print`, fix: "Expand them on paper" },
    wide: { problem: `${plural(count, "wide table", "wide tables")}: about ${Math.round(cut * 100)}% is cut off the page`, fix: "Shrink to fit the page" },
    clipped: { problem: `${plural(count, "scroll box prints", "scroll boxes print")} only the part in view`, fix: "Print their full content" },
    links: { problem: `${plural(count, "link prints", "links print")} without an address`, fix: "Write the address after each link" },
  }[kind]
}

export interface PrintGuardProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** What gets printed. Defaults to the whole page. */
  target?: React.RefObject<HTMLElement | null>
  /** Printable width in CSS px. Default: A4 with 1 cm margins (718). Letter is about 739. */
  pageWidth?: number
  /** Ctrl+P / Cmd+P can't be stopped, so apply every fix to those printouts too, then offer a review. */
  autoFix?: boolean
  /** Check as soon as it mounts and show what would be lost, without waiting for a click. */
  checkOnMount?: boolean
  /** Wording per issue; return `problem` and `fix`. */
  describeIssue?: (issue: PrintIssue) => { problem: string; fix: string }
  /** Print button content. */
  printLabel?: React.ReactNode
  /** Panel heading. */
  title?: string
  /** Button text to show an affected element. */
  showLabel?: string
  /** Button text to print with fixes. */
  printFixedLabel?: string
  /** Button text to print without fixes. */
  printAsIsLabel?: string
  /** Cancel button text. */
  cancelLabel?: string
  /** `{count}` is filled in. */
  autoFixedText?: string
  /** Button text to review an auto-fixed printout. */
  reviewLabel?: string
}

/**
 * Stops the printout that doesn't match the screen. Before printing it checks
 * what paper will lose: light text on dark backgrounds the browser drops,
 * collapsed sections, tables wider than the page (measured at their narrowest),
 * scroll boxes that print only what's in view, and links without their address.
 * Each fix is print-only, so the screen never changes. Ctrl+P can't be
 * intercepted, so those printouts get the fixes automatically and a review after.
 */
export function PrintGuard({
  target,
  pageWidth = A4_CONTENT_WIDTH,
  autoFix = true,
  checkOnMount = false,
  describeIssue = describePrintIssue,
  printLabel = "Print",
  title = "This won't print the way it looks",
  showLabel = "Show",
  printFixedLabel = "Print with fixes",
  printAsIsLabel = "Print as is",
  cancelLabel = "Cancel",
  autoFixedText = "Fixed {count} for that printout.",
  reviewLabel = "Review",
  className,
  ...props
}: PrintGuardProps) {
  const [issues, setIssues] = React.useState<PrintIssue[]>([])
  const [open, setOpen] = React.useState(false)
  const [skipped, setSkipped] = React.useState<Set<PrintIssueKind>>(new Set())
  const [autoFixed, setAutoFixed] = React.useState<number>()
  const revert = React.useRef<(() => void) | null>(null)
  const viaButton = React.useRef(false)
  const panelRef = React.useRef<HTMLDivElement>(null)
  const printRef = React.useRef<HTMLButtonElement>(null)
  const titleId = React.useId()
  const focusPanel = React.useRef(false)

  const scan = React.useCallback(() => scanForPrint(target?.current ?? document.body, { pageWidth }), [target, pageWidth])

  React.useEffect(() => {
    // beforeprint/afterprint, with the print media query as a backup; the refs make double calls harmless.
    const before = () => {
      if (revert.current || viaButton.current || !autoFix) return
      const found = scan()
      revert.current = applyPrintFixes(found)
      if (found.length) setAutoFixed(found.reduce((sum, issue) => sum + issue.count, 0))
    }
    const after = () => {
      revert.current?.()
      revert.current = null
      viaButton.current = false
    }
    const media = matchMedia("print")
    const onMedia = (event: MediaQueryListEvent) => (event.matches ? before() : after())
    window.addEventListener("beforeprint", before)
    window.addEventListener("afterprint", after)
    media.addEventListener("change", onMedia)
    return () => {
      window.removeEventListener("beforeprint", before)
      window.removeEventListener("afterprint", after)
      media.removeEventListener("change", onMedia)
    }
  }, [autoFix, scan])

  // Focus follows a click on Print, never a check that ran by itself.
  React.useEffect(() => {
    if (open && focusPanel.current) panelRef.current?.focus()
    focusPanel.current = false
  }, [open])

  const print = (fixes: PrintIssue[]) => {
    setOpen(false)
    setAutoFixed(undefined)
    viaButton.current = true
    revert.current = applyPrintFixes(fixes)
    window.print()
  }
  const review = () => {
    const found = scan()
    setIssues(found)
    setSkipped(new Set())
    setAutoFixed(undefined)
    if (found.length) setOpen(true)
    return found
  }
  const close = () => {
    setOpen(false)
    printRef.current?.focus()
  }
  const show = (issue: PrintIssue) => {
    const hidden = !issue.first.checkVisibility()
    const element = hidden ? (document.querySelector<HTMLElement>(`[aria-controls="${issue.first.id}"]`) ?? issue.first) : issue.first
    const still = matchMedia("(prefers-reduced-motion: reduce)").matches
    element.scrollIntoView({ block: "center", behavior: still ? "auto" : "smooth" })
    if (!still)
      element.animate([{ outline: "3px solid rgb(245 158 11)", outlineOffset: "2px" }, { outline: "3px solid rgb(245 158 11 / 0)", outlineOffset: "6px" }], {
        duration: 400,
        delay: 250,
        iterations: 2,
        easing: "ease-out",
      })
  }
  React.useEffect(() => {
    if (!checkOnMount) return
    const found = scan()
    setIssues(found)
    setOpen(found.length > 0)
  }, [checkOnMount, scan])

  const chosen = issues.filter((issue) => !skipped.has(issue.kind))

  return (
    <div data-slot="print-guard" className={cn("w-full", className)} {...props}>
      <style>{printFixCss}</style>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
        <button
          ref={printRef}
          type="button"
          aria-expanded={open}
          onClick={() => {
            focusPanel.current = true
            if (review().length === 0) print([])
          }}
          className={cn(button, "border bg-background shadow-xs hover:bg-accent dark:border-input dark:bg-input/30 dark:hover:bg-input/50")}
        >
          <Printer aria-hidden className="size-4" />
          {printLabel}
        </button>
        <p role="status" className="flex items-center gap-2 text-xs text-muted-foreground">
          {autoFixed !== undefined && (
            <>
              {autoFixedText.replace("{count}", plural(autoFixed, "thing", "things"))}
              <button type="button" onClick={review} className={fixClass}>
                {reviewLabel}
              </button>
            </>
          )}
        </p>
      </div>

      <div className={cn("grid transition-[grid-template-rows,opacity] duration-300 ease-out motion-reduce:transition-none", open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0")}>
        <div className="min-h-0 overflow-hidden" inert={!open}>
          <div
            ref={panelRef}
            tabIndex={-1}
            role="region"
            aria-labelledby={titleId}
            onKeyDown={(event) => event.key === "Escape" && close()}
            className="mt-2 rounded-lg border border-amber-500/30 bg-background bg-linear-to-r from-amber-500/10 to-amber-500/10 text-sm text-amber-950 outline-none dark:text-amber-50"
          >
            <p id={titleId} className="flex items-center gap-2 px-3 pt-2.5 font-medium">
              <TriangleAlert aria-hidden className="size-4 shrink-0 text-amber-600 dark:text-amber-400" />
              {title}
            </p>
            <ul className="grid gap-2 px-3 py-2.5">
              {issues.map((issue) => {
                const Icon = icons[issue.kind]
                const text = describeIssue(issue)
                const checked = !skipped.has(issue.kind)
                return (
                  <li key={issue.kind} className="flex items-start gap-2">
                    <input
                      id={`${titleId}-${issue.kind}`}
                      type="checkbox"
                      checked={checked}
                      onChange={() => setSkipped((previous) => new Set(checked ? [...previous, issue.kind] : [...previous].filter((kind) => kind !== issue.kind)))}
                      className="mt-0.5 size-4 shrink-0 accent-amber-700 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50 dark:accent-amber-400"
                    />
                    <label htmlFor={`${titleId}-${issue.kind}`} className="min-w-0 flex-1">
                      <span className="flex items-start gap-1.5">
                        <Icon aria-hidden className="mt-0.5 size-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
                        {text.problem}
                      </span>
                      <span className={cn("block pl-5 text-xs text-amber-900/75 dark:text-amber-100/75", !checked && "line-through")}>{text.fix}</span>
                    </label>
                    <button type="button" onClick={() => show(issue)} className={fixClass}>
                      {showLabel}
                    </button>
                  </li>
                )
              })}
            </ul>
            <div className="flex flex-wrap justify-end gap-2 border-t border-amber-500/20 px-3 py-2">
              <button type="button" onClick={close} className={cn(small, "hover:bg-amber-500/15")}>
                {cancelLabel}
              </button>
              <button type="button" onClick={() => print([])} className={cn(small, "border border-amber-700/25 hover:bg-amber-500/15 dark:border-amber-300/25")}>
                {printAsIsLabel}
              </button>
              <button
                type="button"
                onClick={() => print(chosen)}
                disabled={chosen.length === 0}
                className={cn(small, "bg-amber-700 text-white hover:bg-amber-800 disabled:opacity-60 dark:bg-amber-400 dark:text-amber-950 dark:hover:bg-amber-300")}
              >
                <Printer aria-hidden className="size-4" />
                {printFixedLabel}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

// Bollard UI — print-guard · MIT licence · https://bollard-ui.vercel.app/components/print-guard

// What a page loses on paper, found in the live DOM, and print-only fixes that undo themselves.
// Browser only: call from events or effects.

export type PrintIssueKind = "dark" | "collapsed" | "wide" | "clipped" | "links"

export interface PrintIssue {
  kind: PrintIssueKind
  /** How many things are affected (sections, tables, links). */
  count: number
  /** The first affected element, to show the user. */
  first: HTMLElement
  /** For "wide": the largest share of a table cut off the page, 0 to 1. */
  cut?: number
  /** Internal: elements to mark and how. */
  marks: { element: HTMLElement; zoom?: number; url?: string }[]
}

/** Default printable width in CSS px: A4 (210 mm) minus 1 cm margins each side. */
export const A4_CONTENT_WIDTH = 718

let canvas: CanvasRenderingContext2D | null | undefined
const colors = new Map<string, { luminance: number; alpha: number }>()

/** Relative luminance (0 to 1) and alpha of any CSS color, oklch and color-mix included, by painting one pixel. */
export function readColor(color: string) {
  const cached = colors.get(color)
  if (cached) return cached
  canvas ??= Object.assign(document.createElement("canvas"), { width: 1, height: 1 }).getContext("2d", { willReadFrequently: true })
  if (!canvas) return { luminance: 0, alpha: 0 }
  canvas.clearRect(0, 0, 1, 1)
  canvas.fillStyle = color
  canvas.fillRect(0, 0, 1, 1)
  const [r, g, b, a] = canvas.getImageData(0, 0, 1, 1).data
  const linear = (value: number) => ((value /= 255) <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4)
  const result = { luminance: 0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b), alpha: a / 255 }
  colors.set(color, result)
  return result
}

const visible = (element: Element) => (element.checkVisibility ? element.checkVisibility() : (element as HTMLElement).offsetParent !== null)
const normalize = (text: string) => text.toLowerCase().replace(/^(https?:\/\/)?(www\.)?/, "").replace(/\/$/, "")

/** The element that paints the background behind `element`, and whether it is dark. */
function backdrop(element: Element) {
  for (let node: Element | null = element; node; node = node.parentElement) {
    const style = getComputedStyle(node)
    if (style.backgroundImage !== "none") return { node, dark: true, exact: style.printColorAdjust === "exact" }
    if (readColor(style.backgroundColor).alpha > 0.5)
      return { node, dark: readColor(style.backgroundColor).luminance < 0.2, exact: style.printColorAdjust === "exact" }
  }
}

/** Scans `root` for what printing would lose. Elements inside `ignore` (the guard's own UI) are skipped. */
export function scanForPrint(root: HTMLElement, { pageWidth = A4_CONTENT_WIDTH, ignore = '[data-slot="print-guard"]' } = {}) {
  const issues: PrintIssue[] = []
  const add = (kind: PrintIssueKind, marks: PrintIssue["marks"], count = marks.length, cut?: number) =>
    marks.length && issues.push({ kind, count, first: marks[0].element, marks, cut })
  const all = [...root.querySelectorAll<HTMLElement>("*")].filter((element) => !element.closest(ignore))

  // Light text whose dark background the browser drops by default ("Background graphics" off).
  const sections = new Set<Element>()
  const ink: PrintIssue["marks"] = []
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  const seen = new Set<Element>()
  for (let text = walker.nextNode(); text; text = walker.nextNode()) {
    const element = text.parentElement
    if (!element || seen.has(element) || !text.textContent?.trim() || element.closest(ignore) || !visible(element)) continue
    seen.add(element)
    const behind = backdrop(element)
    if (!behind?.dark || behind.exact || readColor(getComputedStyle(element).color).luminance < 0.5) continue
    sections.add(behind.node)
    ink.push({ element })
  }
  add("dark", ink, sections.size)

  // Closed <details> and aria-expanded="false" panels print exactly as they look: closed.
  const collapsed = all.flatMap((element): HTMLElement[] => {
    if (element instanceof HTMLDetailsElement) return element.open ? [] : [element]
    if (element.getAttribute("aria-expanded") !== "false") return []
    const panel = document.getElementById(element.getAttribute("aria-controls") ?? "")
    return panel && root.contains(panel) && !visible(panel) ? [panel] : []
  })
  add("collapsed", collapsed.map((element) => ({ element })))

  // Tables, code and scroll boxes wider than the room they get on paper. Tables are measured at their narrowest.
  // That room is the element's box on screen, scaled up when the screen is narrower than the paper.
  const wide: PrintIssue["marks"] = []
  const viewport = document.documentElement.clientWidth
  let cut = 0
  for (const element of all) {
    if (!visible(element) || wide.some((mark) => mark.element.contains(element))) continue
    const style = getComputedStyle(element)
    const scrolls = /auto|scroll|hidden/.test(style.overflowX) && element.scrollWidth > element.clientWidth + 1
    if (!scrolls && element.tagName !== "TABLE" && element.tagName !== "PRE") continue
    let width = element.scrollWidth
    if (element.tagName === "TABLE") {
      const previous = element.style.width
      element.style.width = "min-content"
      width = element.offsetWidth
      element.style.width = previous
    }
    const box = scrolls ? element.clientWidth : (element.parentElement?.clientWidth ?? pageWidth)
    const room = Math.min(pageWidth, viewport < pageWidth ? (box * pageWidth) / viewport : box)
    if (width <= room + 1) continue
    cut = Math.max(cut, 1 - room / width)
    wide.push({ element, zoom: Math.max(0.5, room / width) })
  }
  add("wide", wide, wide.length, cut)

  // Fixed-height scroll boxes print only the part currently in view.
  const clipped = all.filter((element) => {
    // Tiny boxes are visually-hidden text (sr-only), not content someone reads.
    if (element === document.body || !visible(element) || element.clientHeight < 24 || element.clientWidth < 24) return false
    return /auto|scroll|hidden/.test(getComputedStyle(element).overflowY) && element.scrollHeight > element.clientHeight + 8
  })
  add("clipped", clipped.map((element) => ({ element })))

  // Links whose text isn't their address: on paper nobody can follow them.
  const links = all.flatMap((element) => {
    if (!(element instanceof HTMLAnchorElement) || !/^(https?|mailto|tel):/.test(element.protocol) || !visible(element)) return []
    const url = element.protocol === "mailto:" || element.protocol === "tel:" ? element.href.replace(/^\w+:/, "") : element.href
    return normalize(element.textContent ?? "").includes(normalize(url)) ? [] : [{ element: element as HTMLElement, url }]
  })
  add("links", links)
  return issues
}

const token: Record<PrintIssueKind, string> = { dark: "ink", collapsed: "reveal", wide: "fit", clipped: "unclip", links: "url" }

/** Marks the issues for the print stylesheet (and opens closed <details>). Returns a function that undoes it all. */
export function applyPrintFixes(issues: PrintIssue[]) {
  const undo: (() => void)[] = []
  for (const issue of issues) {
    for (const { element, zoom, url } of issue.marks) {
      if (element instanceof HTMLDetailsElement) {
        element.open = true
        undo.push(() => (element.open = false))
        continue
      }
      const before = element.dataset.cuiPrint
      element.dataset.cuiPrint = `${before ?? ""} ${token[issue.kind]}`.trim()
      if (zoom) element.style.setProperty("--cui-print-zoom", String(zoom))
      if (url) element.dataset.cuiPrintUrl = url
      undo.push(() => {
        if (before === undefined) delete element.dataset.cuiPrint
        else element.dataset.cuiPrint = before
        element.style.removeProperty("--cui-print-zoom")
        delete element.dataset.cuiPrintUrl
      })
    }
  }
  return () => undo.reverse().forEach((step) => step())
}

/** Print-only rules for the marks above. Nothing changes on screen. */
export const printFixCss = `@media print {
  [data-cui-print~="ink"] { color: #000 !important; text-shadow: none !important; }
  [data-cui-print~="reveal"] { display: block !important; }
  [data-cui-print~="fit"] { zoom: var(--cui-print-zoom, 1); overflow: visible !important; max-width: none !important; }
  [data-cui-print~="unclip"] { overflow: visible !important; max-height: none !important; height: auto !important; }
  a[data-cui-print~="url"]::after { content: " (" attr(data-cui-print-url) ")"; font-size: 0.85em; overflow-wrap: anywhere; }
  [data-slot="print-guard"] { display: none !important; }
}`
